-- ES/DE/FR translations for the rest of Germany's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Totalmente descentralizado — sin compensación', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las especificaciones de formato, los requisitos técnicos de ZRE/OZG-RE y la postura de aplicación de sanciones siguen evolucionando a medida que se acercan las fases de 2027 y 2028 — confirme los requisitos actuales directamente con el BMF o su proveedor de ERP/facturación electrónica antes de construir una integración.', 'La reforma alemana es inusualmente gradual por diseño — primero un puro mandato de recepción, después la emisión implementada por fases estrictamente según la facturación de la empresa, sin ninguna obligación de reporte nacional asociada (todavía).', 'Alemania acepta dos formatos nacionales genuinamente distintos en paralelo, además de Peppol BIS como tercera opción — aquí hay una elección real, a diferencia de la mayoría de los países con CTC.', 'Esta es la mayor diferencia estructural respecto a Francia, Italia o Polonia: Alemania no tiene autoridad de compensación ni canal obligatorio para el B2B en absoluto.', 'A diferencia de Rumanía, Francia o Bélgica, no hay ningún directorio al que unirse ni cuenta que abrir para el B2B — el modelo descentralizado de Alemania hace que el "registro" trate en realidad de la preparación interna y, cuando corresponda, del portal específico de su cliente gubernamental.', 'Alemania no tiene una multa dedicada a la facturación electrónica — el incumplimiento se integra en la ley de IVA y contabilidad ya existente, y el riesgo más agudo no es en absoluto una multa gubernamental.' FROM countries WHERE name_en = 'Germany';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Vollständig dezentralisiert — kein Clearing', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Formatspezifikationen, technische Anforderungen von ZRE/OZG-RE und die Durchsetzungshaltung entwickeln sich weiter, während sich die Phasen 2027 und 2028 nähern — bestätigen Sie aktuelle Anforderungen direkt beim BMF oder Ihrem ERP-/E-Invoicing-Anbieter, bevor Sie eine Integration aufbauen.', 'Deutschlands Reform ist bewusst ungewöhnlich schrittweise angelegt — zunächst eine reine Empfangspflicht, dann die Ausstellung strikt nach Unternehmensumsatz gestaffelt eingeführt, ohne (bisher) daran geknüpfte inländische Meldepflicht.', 'Deutschland akzeptiert zwei genuin unterschiedliche nationale Formate nebeneinander, plus Peppol BIS als dritte Option — hier gibt es echte Wahlfreiheit, anders als in den meisten CTC-Ländern.', 'Dies ist der größte strukturelle Unterschied zu Frankreich, Italien oder Polen: Deutschland hat überhaupt keine Clearing-Behörde und keinen vorgeschriebenen Kanal für B2B.', 'Anders als Rumänien, Frankreich oder Belgien gibt es kein Verzeichnis, dem man beitritt, oder Konto, das man für B2B eröffnet — Deutschlands dezentralisiertes Modell bedeutet, dass "Registrierung" wirklich interne Bereitschaft und, wo relevant, das Portal Ihres konkreten Regierungskunden betrifft.', 'Deutschland hat kein eigenes E-Invoicing-Bußgeld — Nichteinhaltung wird in das bestehende Umsatzsteuer- und Buchführungsrecht eingegliedert, und das schärfste Risiko ist überhaupt kein staatliches Bußgeld.' FROM countries WHERE name_en = 'Germany';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Entièrement décentralisé — aucun contrôle', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les spécifications de format, les exigences techniques ZRE/OZG-RE et la posture d''application des sanctions continuent d''évoluer à l''approche des phases 2027 et 2028 — confirmez les exigences actuelles directement auprès du BMF ou de votre fournisseur ERP/facturation électronique avant de construire une intégration.', 'La réforme allemande est délibérément atypiquement graduelle — d''abord une pure obligation de réception, puis l''émission déployée par phases strictement selon le chiffre d''affaires de l''entreprise, sans obligation de déclaration domestique associée (pour l''instant).', 'L''Allemagne accepte deux formats nationaux véritablement distincts en parallèle, plus Peppol BIS comme troisième option — il y a un véritable choix ici, contrairement à la plupart des pays à CTC.', 'C''est la plus grande différence structurelle par rapport à la France, l''Italie ou la Pologne : l''Allemagne n''a aucune autorité de contrôle ni canal imposé pour le B2B.', 'Contrairement à la Roumanie, la France ou la Belgique, il n''existe aucun annuaire à rejoindre ni compte à ouvrir pour le B2B — le modèle décentralisé de l''Allemagne signifie que « l''inscription » concerne réellement la préparation interne et, le cas échéant, le portail propre à votre client gouvernemental.', 'L''Allemagne n''a pas d''amende dédiée à la facturation électronique — la non-conformité est intégrée au droit de la TVA et de la comptabilité déjà existant, et le risque le plus aigu n''est pas du tout une amende gouvernementale.' FROM countries WHERE name_en = 'Germany';

