INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'XRechnung', '[["Tipo", "XML puro — sin capa visual"], ["Sintaxis", "UBL 2.1 o UN/CEFACT CII"], ["Versión actual", "XRechnung 3.0.2 (avanzando hacia 4.0)"], ["Obligatorio para", "Todas las facturas B2G; cada vez más usado para B2B"]]', 'Dado que XRechnung no tiene una representación legible por humanos integrada, los destinatarios necesitan software que realmente pueda mostrar o procesar el XML — esto explica en parte por qué ZUGFeRD suele preferirse para B2B.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'XRechnung';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'XRechnung', '[["Typ", "Reines XML — keine visuelle Schicht"], ["Syntax", "UBL 2.1 oder UN/CEFACT CII"], ["Aktuelle Version", "XRechnung 3.0.2 (Umstieg auf 4.0)"], ["Verpflichtend für", "Alle B2G-Rechnungen; zunehmend auch für B2B genutzt"]]', 'Da XRechnung keine integrierte menschenlesbare Darstellung besitzt, benötigen Empfänger Software, die das XML tatsächlich anzeigen oder verarbeiten kann — das ist mit ein Grund, warum ZUGFeRD für B2B oft bevorzugt wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'XRechnung';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'XRechnung', '[["Type", "XML pur — aucune couche visuelle"], ["Syntaxe", "UBL 2.1 ou UN/CEFACT CII"], ["Version actuelle", "XRechnung 3.0.2 (passage à la 4.0)"], ["Obligatoire pour", "Toutes les factures B2G ; de plus en plus utilisé pour le B2B"]]', 'Comme XRechnung n''intègre aucun rendu lisible par l''humain, les destinataires ont besoin d''un logiciel capable d''afficher ou de traiter réellement le XML — c''est en partie pourquoi ZUGFeRD est souvent préféré pour le B2B.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'XRechnung';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'ZUGFeRD', '[["Tipo", "Híbrido — PDF/A-3 + XML incrustado"], ["Versión actual", "ZUGFeRD 2.3.x (se requiere 2.1+)"], ["Compatible con", "Factur-X (Francia) desde v2.1"], ["Preferido para", "B2B — legible sin software especializado"]]', 'El XML incrustado sigue la misma familia de sintaxis CII que la opción CII de XRechnung — por lo que un pipeline bien construido a menudo puede generar ambos formatos a partir del mismo modelo de datos subyacente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'ZUGFeRD';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'ZUGFeRD', '[["Typ", "Hybrid — PDF/A-3 + eingebettetes XML"], ["Aktuelle Version", "ZUGFeRD 2.3.x (2.1+ erforderlich)"], ["Kompatibel mit", "Factur-X (Frankreich) seit v2.1"], ["Bevorzugt für", "B2B — ohne Spezialsoftware lesbar"]]', 'Das eingebettete XML folgt derselben CII-Syntaxfamilie wie die CII-Option von XRechnung — eine gut aufgebaute Pipeline kann daher oft beide Formate aus demselben zugrunde liegenden Datenmodell erzeugen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'ZUGFeRD';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'ZUGFeRD', '[["Type", "Hybride — PDF/A-3 + XML intégré"], ["Version actuelle", "ZUGFeRD 2.3.x (2.1+ requis)"], ["Compatible avec", "Factur-X (France) depuis la v2.1"], ["Préféré pour", "B2B — lisible sans logiciel spécialisé"]]', 'Le XML intégré suit la même famille de syntaxe CII que l''option CII de XRechnung — un pipeline bien conçu peut donc souvent générer les deux formats à partir du même modèle de données sous-jacent.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'ZUGFeRD';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio (§14 UStG)', '[["Datos de las partes", "Nombre, dirección, NIF-IVA del proveedor y del cliente"], ["Detalle de la transacción", "Descripción, cantidad, precio unitario, fecha de suministro"], ["Detalle fiscal", "Importe neto, tipo de IVA, importe de IVA, total bruto, indicadores de inversión del sujeto pasivo/exención"], ["Firma digital", "No requerida"]]', 'Todo esto debe residir en los propios datos estructurados — adjuntar un PDF con apariencia conforme junto a un XML no conforme no satisface el mandato. "XML" por sí solo tampoco es un indicador de cumplimiento — debe ser una implementación reconocida de EN 16931.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'Mandatory content (§14 UStG)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalt (§14 UStG)', '[["Parteidaten", "Name, Anschrift, USt-IdNr. für Lieferant & Kunde"], ["Transaktionsdetails", "Beschreibung, Menge, Einzelpreis, Lieferdatum"], ["Steuerdetails", "Nettobetrag, USt-Satz, USt-Betrag, Bruttosumme, Reverse-Charge-/Befreiungskennzeichen"], ["Digitale Signatur", "Nicht erforderlich"]]', 'All dies muss in den strukturierten Daten selbst enthalten sein — ein konform aussehendes PDF neben einem nicht konformen XML anzuhängen, erfüllt die Vorgabe nicht. "XML" allein ist ebenfalls kein Compliance-Indikator — es muss eine anerkannte EN-16931-Implementierung sein.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'Mandatory content (§14 UStG)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire (§14 UStG)', '[["Données des parties", "Nom, adresse, numéro de TVA du fournisseur et du client"], ["Détail de la transaction", "Description, quantité, prix unitaire, date de livraison"], ["Détail fiscal", "Montant net, taux de TVA, montant de TVA, total brut, indicateurs d''autoliquidation/exonération"], ["Signature numérique", "Non requise"]]', 'Tout cela doit résider dans les données structurées elles-mêmes — joindre un PDF d''apparence conforme à côté d''un XML non conforme ne satisfait pas l''obligation. Le « XML » seul n''est pas non plus un indicateur de conformité — il doit s''agir d''une implémentation EN 16931 reconnue.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'Mandatory content (§14 UStG)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Particularidades del CIUS alemán', '[["BT-72 (fecha real de entrega)", "Opcional en EN 16931 → obligatorio en el CIUS alemán"], ["Códigos de medio de pago B2G", "Lista restringida (p. ej. 30 = transferencia, 58 = SEPA)"], ["Archivo", "8 años, conforme a GoBD, formato estructurado original"]]', 'Guardar solo una copia impresa de una factura ZUGFeRD en lugar del archivo original infringe las normas de conservación de registros de GoBD — el XML incrustado es la parte que debe conservarse, no solo la representación en PDF.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'German CIUS quirks';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Deutsche CIUS-Besonderheiten', '[["BT-72 (tatsächliches Lieferdatum)", "Optional in EN 16931 → verpflichtend in der deutschen CIUS"], ["B2G-Zahlungsmittelcodes", "Eingeschränkte Liste (z. B. 30 = Überweisung, 58 = SEPA)"], ["Archivierung", "8 Jahre, GoBD-konform, ursprüngliches strukturiertes Format"]]', 'Nur eine gedruckte Kopie einer ZUGFeRD-Rechnung statt der Originaldatei aufzubewahren, verstößt gegen die GoBD-Aufbewahrungsregeln — das eingebettete XML ist der Teil, der erhalten bleiben muss, nicht nur die PDF-Darstellung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'German CIUS quirks';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Particularités du CIUS allemand', '[["BT-72 (date de livraison réelle)", "Facultatif dans l''EN 16931 → obligatoire dans le CIUS allemand"], ["Codes de moyen de paiement B2G", "Liste restreinte (ex. 30 = virement, 58 = SEPA)"], ["Archivage", "8 ans, conforme GoBD, format structuré d''origine"]]', 'Ne conserver qu''une copie imprimée d''une facture ZUGFeRD au lieu du fichier d''origine enfreint les règles de conservation GoBD — le XML intégré est l''élément qui doit être préservé, pas seulement le rendu PDF.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'file_format' AND dct.title = 'German CIUS quirks';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2B: totalmente descentralizado', '[["Autoridad de compensación", "Ninguna"], ["Canal obligatorio", "Ninguno — cualquier método acordado"], ["Canales aceptados", "Correo electrónico, portal/enlace de descarga, EDI, FTP/FTPS, servicios web, Peppol"]]', 'El mandato regula el formato de la factura, no cómo viaja. Dos socios comerciales son libres de acordar el método de transmisión que les convenga, siempre que el propio archivo sea una factura estructurada conforme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2B: fully decentralised';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2B: vollständig dezentralisiert', '[["Clearing-Behörde", "Keine"], ["Vorgeschriebener Kanal", "Keiner — jede vereinbarte Methode"], ["Akzeptierte Kanäle", "E-Mail, Portal-/Download-Link, EDI, FTP/FTPS, Webservices, Peppol"]]', 'Die Vorgabe regelt das Format der Rechnung, nicht ihren Übertragungsweg. Zwei Handelspartner können frei jede für sie passende Übertragungsmethode vereinbaren, solange die Datei selbst eine konforme strukturierte Rechnung ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2B: fully decentralised';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2B : entièrement décentralisé', '[["Autorité de contrôle", "Aucune"], ["Canal imposé", "Aucun — toute méthode convenue"], ["Canaux acceptés", "E-mail, lien de portail/téléchargement, EDI, FTP/FTPS, services web, Peppol"]]', 'L''obligation régit le format de la facture, pas son mode de transmission. Deux partenaires commerciaux sont libres de convenir de la méthode de transmission qui leur convient, tant que le fichier lui-même est une facture structurée conforme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2B: fully decentralised';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2G: dos portales federales', '[["ZRE", "Administración federal directa (ministerios + organismos directamente subordinados)"], ["OZG-RE", "Administración federal indirecta + varios estados federados"], ["Identificador de enrutamiento", "Leitweg-ID (formato XX-XXXXXXXXXX-XX)"]]', 'Su autoridad contratante le indica qué plataforma y Leitweg-ID usar — consulte su contrato o los términos de contratación si tiene dudas. Las autoridades también deben ofrecer Peppol como opción de transmisión cuando sea posible el intercambio automatizado.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2G: two federal portals';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2G: zwei Bundesportale', '[["ZRE", "Unmittelbare Bundesverwaltung (Ministerien + direkt nachgeordnete Behörden)"], ["OZG-RE", "Mittelbare Bundesverwaltung + mehrere Bundesländer"], ["Routing-Kennung", "Leitweg-ID (Format XX-XXXXXXXXXX-XX)"]]', 'Ihre Vergabestelle teilt Ihnen mit, welche Plattform und Leitweg-ID zu verwenden ist — prüfen Sie im Zweifel Ihren Vertrag oder die Vergabebedingungen. Behörden müssen zudem Peppol als Übertragungsoption anbieten, wo automatisierter Austausch möglich ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2G: two federal portals';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2G : deux portails fédéraux', '[["ZRE", "Administration fédérale directe (ministères + organismes directement subordonnés)"], ["OZG-RE", "Administration fédérale indirecte + plusieurs Länder"], ["Identifiant de routage", "Leitweg-ID (format XX-XXXXXXXXXX-XX)"]]', 'Votre autorité contractante vous indique quelle plateforme et quel Leitweg-ID utiliser — vérifiez votre contrat ou les conditions de marché en cas de doute. Les autorités doivent également proposer Peppol comme option de transmission lorsque l''échange automatisé est possible.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'B2G: two federal portals';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Causas comunes de rechazo B2G', '[["Leitweg-ID faltante/incorrecto", "Debe aparecer en BT-10 (BuyerReference)"], ["Desglose de IVA no válido", "Cada categoría de IVA necesita un desglose separado"], ["Tamaño del adjunto", "ZRE limita los adjuntos incrustados a 5 MB"], ["Discrepancia de perfil", "Usar XRechnung 2.x cuando se requiere 3.x"]]', 'Si su factura rebota desde ZRE u OZG-RE, estas cuatro causas cubren la gran mayoría de los rechazos reales — verifique primero el Leitweg-ID y la versión del perfil.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Common B2G rejection causes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Häufige Ablehnungsgründe bei B2G', '[["Fehlende/falsche Leitweg-ID", "Muss in BT-10 (BuyerReference) erscheinen"], ["Ungültige USt-Aufschlüsselung", "Jede USt-Kategorie benötigt eine eigene Aufschlüsselung"], ["Anhanggröße", "ZRE begrenzt eingebettete Anhänge auf 5 MB"], ["Profil-Mismatch", "Verwendung von XRechnung 2.x, obwohl 3.x erforderlich ist"]]', 'Wenn Ihre Rechnung von ZRE oder OZG-RE abgewiesen wird, decken diese vier Ursachen die große Mehrheit der realen Ablehnungen ab — prüfen Sie zuerst die Leitweg-ID und die Profilversion.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Common B2G rejection causes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Causes courantes de rejet B2G', '[["Leitweg-ID manquant/erroné", "Doit apparaître dans le BT-10 (BuyerReference)"], ["Ventilation de TVA invalide", "Chaque catégorie de TVA nécessite une ventilation distincte"], ["Taille de pièce jointe", "ZRE limite les pièces jointes intégrées à 5 Mo"], ["Discordance de profil", "Utilisation de XRechnung 2.x alors que la 3.x est requise"]]', 'Si votre facture est rejetée par ZRE ou OZG-RE, ces quatre causes couvrent la grande majorité des rejets réels — vérifiez d''abord le Leitweg-ID et la version du profil.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Common B2G rejection causes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Acceso de auditoría', '[["Acceso Z1 / Z2", "Acceso directo de solo lectura a su sistema contable"], ["Acceso Z3", "Exportación de datos estructurados de los registros de facturación electrónica"], ["Canal de envío", "ELSTER (cuando corresponda)"]]', 'Las autoridades fiscales alemanas pueden solicitar cualquiera de estos tres modos de acceso durante una auditoría — mantener las facturas archivadas sistemáticamente en un formato estándar y exportable reduce sustancialmente la fricción de la auditoría.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Audit access';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Prüfungszugriff', '[["Z1-/Z2-Zugriff", "Direkter lesender Zugriff auf Ihr Buchhaltungssystem"], ["Z3-Zugriff", "Strukturierter Datenexport der E-Rechnungsdatensätze"], ["Übermittlungskanal", "ELSTER (soweit zutreffend)"]]', 'Deutsche Finanzbehörden können bei einer Prüfung jede dieser drei Zugriffsarten verlangen — Rechnungen systematisch in einem standardisierten, exportierbaren Format zu archivieren verringert die Prüfungsreibung erheblich.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Audit access';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Accès d''audit', '[["Accès Z1 / Z2", "Accès direct en lecture seule à votre système comptable"], ["Accès Z3", "Export de données structurées des registres de factures électroniques"], ["Canal de soumission", "ELSTER (le cas échéant)"]]', 'Les autorités fiscales allemandes peuvent demander l''un de ces trois modes d''accès lors d''un contrôle — archiver systématiquement les factures dans un format standard et exportable réduit sensiblement les frictions lors d''un audit.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'scope_transmission' AND dct.title = 'Audit access';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '💸 El riesgo real es la deducción de IVA de su comprador', NULL, NULL, 'Una factura no conforme se considera no emitida correctamente — su cliente no puede deducir el IVA soportado hasta que reemita una válida. En la práctica, esta presión comercial de los compradores es un impulsor de cumplimiento más fuerte que la propia multa legal.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '💸 The real risk is your buyer''s VAT deduction';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '💸 Das eigentliche Risiko ist der Vorsteuerabzug Ihres Käufers', NULL, NULL, 'Eine nicht konforme Rechnung gilt als nicht ordnungsgemäß ausgestellt — Ihr Kunde kann die Vorsteuer erst abziehen, wenn Sie eine gültige Rechnung neu ausstellen. In der Praxis ist dieser kommerzielle Druck der Käufer ein stärkerer Compliance-Treiber als das gesetzliche Bußgeld selbst.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '💸 The real risk is your buyer''s VAT deduction';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '💸 Le risque réel est la déduction de TVA de votre acheteur', NULL, NULL, 'Une facture non conforme est considérée comme non correctement émise — votre client ne peut pas déduire la TVA en amont tant que vous n''en réémettez pas une valable. En pratique, cette pression commerciale des acheteurs est un moteur de conformité plus fort que l''amende légale elle-même.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '💸 The real risk is your buyer''s VAT deduction';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🕊️ Sin sanciones durante la transición 2025-2026', NULL, NULL, 'Aunque las facturas en papel y PDF siguen estando permitidas por acuerdo mutuo durante el periodo de transición, no se aplican multas por usarlas — se espera que la aplicación se intensifique una vez que comience realmente la fase obligatoria de cada empresa.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '🕊️ No penalties during 2025–2026 transition';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🕊️ Keine Sanktionen während des Übergangs 2025-2026', NULL, NULL, 'Während Papier- und PDF-Rechnungen im Übergangszeitraum bei gegenseitigem Einverständnis weiterhin zulässig sind, fallen dafür keine Bußgelder an — die Durchsetzung dürfte sich verschärfen, sobald die verpflichtende Phase für das jeweilige Unternehmen tatsächlich beginnt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '🕊️ No penalties during 2025–2026 transition';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🕊️ Aucune sanction pendant la transition 2025-2026', NULL, NULL, 'Bien que les factures papier et PDF restent autorisées d''un commun accord pendant la période de transition, aucune amende ne s''applique pour leur utilisation — l''application devrait se durcir une fois que la phase obligatoire de chaque entreprise commence réellement.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '🕊️ No penalties during 2025–2026 transition';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📁 Riesgo de archivo GoBD', NULL, NULL, 'No conservar el archivo estructurado original (por ejemplo, guardar solo una copia impresa) puede desencadenar multas o, en casos graves, permitir que las autoridades fiscales estimen su base imponible en lugar de basarse en sus registros.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '📁 GoBD archiving risk';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📁 GoBD-Archivierungsrisiko', NULL, NULL, 'Wird die ursprüngliche strukturierte Datei nicht aufbewahrt (z. B. nur eine gedruckte Kopie), kann dies Bußgelder auslösen oder in schwerwiegenden Fällen den Finanzbehörden erlauben, Ihre Steuerbemessungsgrundlage zu schätzen, statt sich auf Ihre Unterlagen zu verlassen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '📁 GoBD archiving risk';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📁 Risque d''archivage GoBD', NULL, NULL, 'Ne pas conserver le fichier structuré d''origine (par exemple, ne garder qu''une copie imprimée) peut entraîner des amendes ou, dans les cas graves, permettre aux autorités fiscales d''estimer votre base d''imposition plutôt que de se fier à vos registres.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Germany' AND dc.section = 'penalties_related' AND dct.title = '📁 GoBD archiving risk';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Determine qué fase se aplica a su caso', 'Compare la facturación del ejercicio anterior con el umbral de 800.000 € para saber si su obligación de emisión comienza en 2027 o 2028 — y confirme si el estatus de Kleinunternehmer (§19 UStG) le exime por completo de emitir.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Work out which phase applies to you';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ermitteln Sie, welche Phase für Sie gilt', 'Vergleichen Sie Ihren Vorjahresumsatz mit der Schwelle von 800.000 €, um zu wissen, ob Ihre Ausstellungspflicht 2027 oder 2028 beginnt — und prüfen Sie, ob der Kleinunternehmerstatus (§19 UStG) Sie ganz von der Ausstellung befreit.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Work out which phase applies to you';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déterminez quelle phase s''applique à vous', 'Comparez votre chiffre d''affaires de l''exercice précédent au seuil de 800 000 € pour savoir si votre obligation d''émission débute en 2027 ou 2028 — et vérifiez si le statut de Kleinunternehmer (§19 UStG) vous exempte entièrement d''émettre.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Work out which phase applies to you';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su formato: XRechnung, ZUGFeRD o Peppol BIS', 'XRechnung se adapta a flujos B2B automatizados de alto volumen; ZUGFeRD se adapta a relaciones donde una persona todavía necesita abrir y leer la factura; Peppol BIS se adapta a empresas ya activas en esa red para otro comercio europeo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Choose your format: XRechnung, ZUGFeRD, or Peppol BIS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihr Format: XRechnung, ZUGFeRD oder Peppol BIS', 'XRechnung eignet sich für automatisierte B2B-Abläufe mit hohem Volumen; ZUGFeRD eignet sich für Beziehungen, in denen ein Mensch die Rechnung noch öffnen und lesen muss; Peppol BIS eignet sich für Unternehmen, die bereits für anderen europäischen Handel in diesem Netzwerk aktiv sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Choose your format: XRechnung, ZUGFeRD, or Peppol BIS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre format : XRechnung, ZUGFeRD ou Peppol BIS', 'XRechnung convient aux flux B2B automatisés à fort volume ; ZUGFeRD convient aux relations où une personne doit encore ouvrir et lire la facture ; Peppol BIS convient aux entreprises déjà actives sur ce réseau pour d''autres échanges européens.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Choose your format: XRechnung, ZUGFeRD, or Peppol BIS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que los datos del §14 UStG residen en el propio archivo estructurado', 'Valide que los datos del proveedor/cliente, el detalle de la transacción y el desglose fiscal completo estén incrustados en el XML — no solo presentes en un PDF legible por humanos que lo acompañe.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Confirm §14 UStG data lives in the structured file itself';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass §14-UStG-Daten in der strukturierten Datei selbst enthalten sind', 'Prüfen Sie, dass Lieferanten-/Kundendaten, Transaktionsdetails und vollständige Steueraufschlüsselung im XML eingebettet sind — nicht nur in einem begleitenden menschenlesbaren PDF vorhanden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Confirm §14 UStG data lives in the structured file itself';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que les données du §14 UStG figurent dans le fichier structuré lui-même', 'Vérifiez que les données fournisseur/client, le détail de la transaction et la ventilation fiscale complète sont intégrés dans le XML — pas seulement présents dans un PDF lisible par l''humain qui l''accompagne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Confirm §14 UStG data lives in the structured file itself';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Para B2G: cree su cuenta ZRE u OZG-RE', 'Regístrese en la plataforma que le indique su cliente del sector público, y confirme el Leitweg-ID correcto para esa autoridad contratante específica antes de su primer envío.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'For B2G: create your ZRE or OZG-RE account';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Für B2G: Richten Sie Ihr ZRE- oder OZG-RE-Konto ein', 'Registrieren Sie sich auf der Plattform, die Ihr öffentlicher Kunde vorgibt, und bestätigen Sie die korrekte Leitweg-ID für diese konkrete Vergabestelle vor Ihrer ersten Einreichung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'For B2G: create your ZRE or OZG-RE account';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Pour le B2G : créez votre compte ZRE ou OZG-RE', 'Inscrivez-vous sur la plateforme indiquée par votre client du secteur public, et confirmez le Leitweg-ID correct pour cette autorité contractante spécifique avant votre première soumission.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'For B2G: create your ZRE or OZG-RE account';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Acuerde un canal de transmisión con cada socio B2B', 'Dado que no hay un canal obligatorio, acuerde esto explícitamente con sus socios comerciales — correo electrónico, un portal compartido, EDI o Peppol son todos válidos siempre que el archivo subyacente sea conforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Agree a transmission channel with each B2B partner';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Vereinbaren Sie mit jedem B2B-Partner einen Übertragungskanal', 'Da es keinen vorgeschriebenen Kanal gibt, klären Sie dies ausdrücklich mit Ihren Handelspartnern — E-Mail, ein gemeinsames Portal, EDI oder Peppol sind alle zulässig, solange die zugrunde liegende Datei konform ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Agree a transmission channel with each B2B partner';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Convenez d''un canal de transmission avec chaque partenaire B2B', 'Comme il n''y a pas de canal imposé, réglez ce point explicitement avec vos partenaires commerciaux — e-mail, portail partagé, EDI ou Peppol sont tous valables tant que le fichier sous-jacent est conforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Agree a transmission channel with each B2B partner';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure un archivo conforme con GoBD', 'Almacene el archivo estructurado original (no una copia impresa) durante el periodo de conservación requerido, y confirme que puede proporcionar acceso de auditoría tipo Z1/Z2/Z3 si la administración tributaria lo solicita.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Set up GoBD-compliant archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine GoBD-konforme Archivierung ein', 'Speichern Sie die ursprüngliche strukturierte Datei (keine gedruckte Kopie) für die erforderliche Aufbewahrungsfrist, und bestätigen Sie, dass Sie bei Bedarf Z1-/Z2-/Z3-artigen Prüfungszugriff bereitstellen können, falls das Finanzamt danach fragt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Set up GoBD-compliant archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage conforme GoBD', 'Conservez le fichier structuré d''origine (pas une copie imprimée) pendant la période de conservation requise, et vérifiez que vous pouvez fournir un accès d''audit de type Z1/Z2/Z3 si l''administration fiscale le demande.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Germany' AND dst.title = 'Set up GoBD-compliant archiving';

